import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Class: ItemBuilder","description":"","frontmatter":{},"headers":[],"relativePath":"api/twine/classes/ItemBuilder.md","filePath":"api/twine/classes/ItemBuilder.md"}'),i={name:"api/twine/classes/ItemBuilder.md"};function n(s,e,d,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<p><a href="./../">twine</a> / ItemBuilder</p><h1 id="class-itembuilder" tabindex="-1">Class: ItemBuilder <a class="header-anchor" href="#class-itembuilder" aria-label="Permalink to &quot;Class: ItemBuilder&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L27" target="_blank" rel="noreferrer">item.ts:27</a></p><p>Fluent builder for a <strong>custom item that does things</strong>. Wrap the same Item you&#39;d <code>give</code> (the single source of truth for its data) and attach opt-in behaviours; <code>toModule(name)</code> turns it into a drop-in <a href="./../interfaces/ConfiguredModule.html">ConfiguredModule</a> you list in a parent module&#39;s <code>imports</code>. Only attached behaviours emit anything.</p><p>const wand = defineItem(Item.STICK.named(&quot;Frost Wand&quot;).modelData(7)) .give() .onAttack((ctx) =&gt; ctx.effect().give(Selector.self(), &quot;slowness&quot;, 5)) .onHeldTick((ctx) =&gt; ctx.particle(...));</p><p>@Module({ name: &quot;courtyard&quot;, imports: [wand.toModule(&quot;frost_wand&quot;)] })</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h3><blockquote><p><strong>new ItemBuilder</strong>(<code>item</code>): <code>ItemBuilder</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L35" target="_blank" rel="noreferrer">item.ts:35</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="item" tabindex="-1">item <a class="header-anchor" href="#item" aria-label="Permalink to &quot;item&quot;">​</a></h5><p><code>ItemValue</code></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>ItemBuilder</code></p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="give" tabindex="-1">give() <a class="header-anchor" href="#give" aria-label="Permalink to &quot;give()&quot;">​</a></h3><blockquote><p><strong>give</strong>(): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L50" target="_blank" rel="noreferrer">item.ts:50</a></p><p>Emit a <code>/function &lt;ns&gt;:zzz/item/&lt;slug&gt;/give</code> that grants the fully-built item to <code>@s</code>.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="holderselector" tabindex="-1">holderSelector() <a class="header-anchor" href="#holderselector" aria-label="Permalink to &quot;holderSelector()&quot;">​</a></h3><blockquote><p><strong>holderSelector</strong>(<code>dp</code>): <code>Selector</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L99" target="_blank" rel="noreferrer">item.ts:99</a></p><p>The held-detection selector: an <code>@a</code> matching whoever is holding this item, via its (once-)registered holding predicate. For consumers that drive their own tick loop instead of <code>onHeldTick</code> - refine it (<code>.volume(...)</code>) and detect holders the same way the item is defined/given. Needs the Datapack to register the predicate.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="dp" tabindex="-1">dp <a class="header-anchor" href="#dp" aria-label="Permalink to &quot;dp&quot;">​</a></h5><p><code>Datapack</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Selector</code></p><hr><h3 id="matchexact" tabindex="-1">matchExact() <a class="header-anchor" href="#matchexact" aria-label="Permalink to &quot;matchExact()&quot;">​</a></h3><blockquote><p><strong>matchExact</strong>(): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L44" target="_blank" rel="noreferrer">item.ts:44</a></p><p>Detect this item by its <strong>full identity</strong> (components/NBT), not just its base id. By default held-detection keys on the base id alone (cheap, and shared with any other definition of the same base item); call this when two items share a base id but must be told apart - e.g. a custom-modelled lantern vs a plain one. See HoldingOptions.exact.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="onattack" tabindex="-1">onAttack() <a class="header-anchor" href="#onattack" aria-label="Permalink to &quot;onAttack()&quot;">​</a></h3><blockquote><p><strong>onAttack</strong>(<code>body</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L62" target="_blank" rel="noreferrer">item.ts:62</a></p><p>Run <code>body</code> (as the attacker) when the player damages an entity while holding the item.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="body" tabindex="-1">body <a class="header-anchor" href="#body" aria-label="Permalink to &quot;body&quot;">​</a></h5><p><a href="./../type-aliases/ItemBehaviour.html"><code>ItemBehaviour</code></a></p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="onheldtick" tabindex="-1">onHeldTick() <a class="header-anchor" href="#onheldtick" aria-label="Permalink to &quot;onHeldTick()&quot;">​</a></h3><blockquote><p><strong>onHeldTick</strong>(<code>body</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L56" target="_blank" rel="noreferrer">item.ts:56</a></p><p>Run <code>body</code> every tick, as (and at) each player holding the item.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="body-1" tabindex="-1">body <a class="header-anchor" href="#body-1" aria-label="Permalink to &quot;body&quot;">​</a></h5><p><a href="./../type-aliases/ItemBehaviour.html"><code>ItemBehaviour</code></a></p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="onrightclick" tabindex="-1">onRightClick() <a class="header-anchor" href="#onrightclick" aria-label="Permalink to &quot;onRightClick()&quot;">​</a></h3><blockquote><p><strong>onRightClick</strong>(<code>body</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L87" target="_blank" rel="noreferrer">item.ts:87</a></p><p>Run <code>body</code> (as and at the holder) on <strong>right-click</strong>, detected via the <code>used:&lt;item&gt;</code> statistic - the reliable carrot-/warped-fungus-on-a-stick technique that works for items <code>onUse</code> can&#39;t see. Costs one tick command + a scoreboard objective; gated by this item&#39;s holding predicate so only this custom item triggers. Use <a href="#matchexact">matchExact</a> when several custom items share the same base id.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="body-2" tabindex="-1">body <a class="header-anchor" href="#body-2" aria-label="Permalink to &quot;body&quot;">​</a></h5><p><a href="./../type-aliases/ItemBehaviour.html"><code>ItemBehaviour</code></a></p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="onuse" tabindex="-1">onUse() <a class="header-anchor" href="#onuse" aria-label="Permalink to &quot;onUse()&quot;">​</a></h3><blockquote><p><strong>onUse</strong>(<code>body</code>): <code>this</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L74" target="_blank" rel="noreferrer">item.ts:74</a></p><p>Run <code>body</code> (as the user) when the player <strong>uses</strong> the item, via a <code>minecraft:using_item</code> advancement. Fires for items the game treats as &quot;in use&quot; on right-click (food, bow, shield, spyglass, …); for items with <em>no</em> use action (a plain stick, a carrot-on-a-stick), it may never fire - reach for <a href="#onrightclick">onRightClick</a> instead.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="body-3" tabindex="-1">body <a class="header-anchor" href="#body-3" aria-label="Permalink to &quot;body&quot;">​</a></h5><p><a href="./../type-aliases/ItemBehaviour.html"><code>ItemBehaviour</code></a></p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>this</code></p><hr><h3 id="register" tabindex="-1">register() <a class="header-anchor" href="#register" aria-label="Permalink to &quot;register()&quot;">​</a></h3><blockquote><p><strong>register</strong>(<code>dp</code>): <code>FunctionRef</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L124" target="_blank" rel="noreferrer">item.ts:124</a></p><p>Materialise this item&#39;s <strong>event</strong> behaviours straight into <code>dp</code> - the give function plus the <code>onUse</code>/<code>onAttack</code> self-revoking advancements - for consumers wiring an item without the module tree (the full sibling of <a href="#registergive">registerGive</a>). Returns the give FunctionRef when <code>give()</code> was set, else <code>undefined</code>.</p><p><code>onHeldTick</code> is <strong>not</strong> wired here: the held sweep needs the framework&#39;s tick loop, which only <a href="#tomodule">toModule</a> (a module in the tree) provides. Calling this with a held behaviour attached throws, so the drop isn&#39;t silent.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="dp-1" tabindex="-1">dp <a class="header-anchor" href="#dp-1" aria-label="Permalink to &quot;dp&quot;">​</a></h5><p><code>Datapack</code></p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>FunctionRef</code> | <code>undefined</code></p><hr><h3 id="registergive" tabindex="-1">registerGive() <a class="header-anchor" href="#registergive" aria-label="Permalink to &quot;registerGive()&quot;">​</a></h3><blockquote><p><strong>registerGive</strong>(<code>dp</code>): <code>FunctionRef</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L108" target="_blank" rel="noreferrer">item.ts:108</a></p><p>Emit the give function and return its FunctionRef, for consumers that wire it up directly (e.g. <code>register(dp)</code>) rather than via <a href="#tomodule">toModule</a>. Idempotent - many callers share one file.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="dp-2" tabindex="-1">dp <a class="header-anchor" href="#dp-2" aria-label="Permalink to &quot;dp&quot;">​</a></h5><p><code>Datapack</code></p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>FunctionRef</code></p><hr><h3 id="tomodule" tabindex="-1">toModule() <a class="header-anchor" href="#tomodule" aria-label="Permalink to &quot;toModule()&quot;">​</a></h3><blockquote><p><strong>toModule</strong>(<code>name</code>): <a href="./../interfaces/ConfiguredModule.html"><code>ConfiguredModule</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/4c7aecb01ce1911b4091ca195d44fb415791a426/twine/src/item.ts#L135" target="_blank" rel="noreferrer">item.ts:135</a></p><p>Compile to a drop-in <a href="./../interfaces/ConfiguredModule.html">ConfiguredModule</a> (name = module/scoreboard id).</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h5><p><code>string</code></p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/ConfiguredModule.html"><code>ConfiguredModule</code></a></p>',110)])])}const b=t(i,[["render",n]]);export{m as __pageData,b as default};
